    const next = vi.fn();

    const err = new Error('mid-stream failure');
    errorHandler(err, {} as never, res, next);

    expect(next).toHaveBeenCalledWith(err);
    expect(res.status).not.toHaveBeenCalled();
    expect(res.json).not.toHaveBeenCalled();
    vi.restoreAllMocks();
  });

  it('responds with 400 and a client-error message when the error is a SyntaxError with status 400', () => {
    vi.spyOn(console, 'error').mockImplementation(() => {});
    const res = mockRes();
    const SyntaxErrorWithStatus = new SyntaxError('Unexpected end of JSON');
    (SyntaxErrorWithStatus as Error & { status: number }).status = 400;

    errorHandler(SyntaxErrorWithStatus, {} as never, res, vi.fn());

    expect(res.status).toHaveBeenCalledWith(400);
    expect(res.json).toHaveBeenCalledWith({
      error: 'Request body is not valid JSON.',
    });
    vi.restoreAllMocks();
  });

  it('responds with the generic 500 when the error is a SyntaxError without a status', () => {
    vi.spyOn(console, 'error').mockImplementation(() => {});
    const res = mockRes();
    errorHandler(new SyntaxError('unrelated parsing bug'), {} as never, res, vi.fn());

    expect(res.status).toHaveBeenCalledWith(500);
    expect(res.json).toHaveBeenCalledWith({
      error: 'Something went wrong on the server. Please try again.',
    });
    vi.restoreAllMocks();
  });
});

